  "fund.withSplitExpensesFund": "С функцией «Делить расходы» касса считает, кто кому сколько должен – например, в квартире, в отпуске или в паре. Списки покупок можно привязать к кассе в разделе «Списки» → «Изменить список». Касса «Семья (все)» автоматически включает всех и хранит договоры без собственной кассы.",
  "fund.withSplitExpensesFund#wg": "С функцией «Делить расходы» касса считает, кто кому сколько должен – например, в квартире, в отпуске или в паре. Списки покупок можно привязать к кассе в разделе «Списки» → «Изменить список». Касса «Квартира (все)» автоматически включает всех и хранит договоры без собственной кассы.",
