  "loc.enterInternetConnectionsAddress": "Укажите в качестве сервера адрес вашего интернет-подключения (например, адрес MyFRITZ!) – обычно это делается SMS-командой, см. руководство к трекеру.",
  "loc.enterShopAddressesUnder": "Адреса магазинов указываются в разделе «Списки → Изменить список покупок» – если у магазина несколько филиалов, то и все они. Если человек задерживается там на некоторое время, запланированная покупка отмечается как выполненная.",
  "loc.familyDoesntSeeYou": "Сейчас семья не видит вас на карте.",
  "loc.familyDoesntSeeYou#wg": "Сейчас квартира не видит вас на карте.",
  "loc.familyGetsMessageSees": "Семья получит сообщение и будет видеть ваше местоположение в реальном времени, пока вы не придёте домой. Начать?",
  "loc.familyGetsMessageSees#wg": "Квартира получит сообщение и будет видеть ваше местоположение в реальном времени, пока вы не придёте домой. Начать?",
  "loc.familySeesLiveDuration": "Семья видит вас на карте в реальном времени – при выборе длительности передача завершится сама.",
  "loc.familySeesLiveDuration#wg": "Квартира видит вас на карте в реальном времени – при выборе длительности передача завершится сама.",
  "loc.fields": "Поля: {felder}",
  "loc.fromPinn": "из pinn.",
  "loc.fromTraccar": "из «Traccar Client»",
  "loc.gettingLocation": "Определяем местоположение …",
  "loc.gpsTracker": "🛰️ GPS-трекер",
  "loc.guide1": "Установите приложение <b>«Traccar Client»</b> (App Store или Google Play, бесплатно).",
  "loc.guide2": "В приложении в поле <b>Device ID</b> (идентификатор устройства) введите:",
  "loc.guide3": "В поле <b>Server URL</b> введите:",
  "loc.guide4": "Точность <b>Medium</b>, расстояние <b>50 м</b>. Тогда приложение отправляет данные только при движении – на месте ничего не отправляется. Если есть другие поля (интервал, heartbeat), отключите heartbeat или поставьте 0.",
  "loc.guide5": "Разрешите доступ к геолокации: <b>Всегда</b> и включите <b>точную геолокацию</b>.",
  "loc.guide6": "Включите переключатель <b>Service / Tracking</b> и <b>всегда оставляйте его включённым</b> – готово. Дальше всё управляется в pinn.: «Передавать постоянно» вкл. или выкл., «Отправить один раз» и SOS. Пока «Передавать постоянно» выключено, никто не видит ваше местоположение, а pinn. не записывает маршрут.",
  "loc.guideIntro": "Без дополнительного приложения «📍 Поделиться местоположением» работает прямо в pinn., но только пока pinn. открыт. Чтобы местоположение передавалось и при закрытом pinn. и заблокированном экране, бесплатное приложение «Traccar Client» отправляет его напрямую в pinn. (сервер Traccar не нужен). Одинаково для iPhone и Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Этот порт нужно пробросить на NAS в FRITZ!Box, потому что трекер подключается из мобильной сети.",
  "loc.haveGoodTripFamily": "Счастливого пути! Семья уведомлена.",
  "loc.haveGoodTripFamily#wg": "Счастливого пути! Квартира уведомлена.",
