  "loc.idRandomLinksPhone": "ID случайный – он связывает телефон с этим человеком.",
  "loc.ifSomeoneArrivesLeaves": "Если кто-то приходит в место или уходит из него, приходит push-уведомление. «Дом» также завершает «Я иду домой».",
  "loc.ifTrackerHasSos": "Если у трекера есть кнопка SOS, pinn. оповестит всю семью push-уведомлением (в течение минуты), как только Traccar обнаружит сигнал тревоги трекера.",
  "loc.ifTrackerHasSos#wg": "Если у трекера есть кнопка SOS, pinn. оповестит всю квартиру push-уведомлением (в течение минуты), как только Traccar обнаружит сигнал тревоги трекера.",
