  "loc.setUpLocation": "Настроить геолокацию",
  "loc.setup": "Настройка · {famDeviceName}",
  "loc.setupIntro": "Телефонам больше ничего не нужно: каждый может поделиться местоположением прямо в pinn. через «Моё местоположение». В фоновом режиме (при закрытом pinn.) телефон отправляет данные через бесплатное приложение «Traccar Client» (iPhone и Android) – напрямую в pinn., сервер Traccar не нужен. Контейнер «traccar» нужен только GPS-трекерам с SIM-картой (например, на ошейнике). Местоположения хранятся на вашем NAS.",
  "loc.setupTrackersUnder": "GPS-трекеры и фоновое приложение настраиваются через {btn}.",
  "loc.shareAlreadyEnded": "Передача местоположения уже завершена.",
  "loc.shareIntro": "Ваша семья видит вас на карте в реальном времени. Данные отправляются только при движении – на месте ничего не отправляется. Когда pinn. закрыт, данные отправляет приложение «Traccar Client», которое вы настроили один раз.",
  "loc.shareIntro#wg": "Ваша квартира видит вас на карте в реальном времени. Данные отправляются только при движении – на месте ничего не отправляется. Когда pinn. закрыт, данные отправляет приложение «Traccar Client», которое вы настроили один раз.",
