  "loc.testSameProcessReal": "Тест: тот же процесс, что и при настоящем вызове помощи (push, окно, карта, адрес) – но только для вас, семья ничего не заметит.",
  "loc.testSameProcessReal#wg": "Тест: тот же процесс, что и при настоящем вызове помощи (push, окно, карта, адрес) – но только для вас, квартира ничего не заметит.",
  "loc.tipSetAddressUnder": "Совет: укажите свой адрес в разделе «Настройки → Дом» – тогда место «Дом» появится автоматически, с push-уведомлением о прибытии и уходе.",
  "loc.traccarClientChooseSend": "В «Traccar Client» выберите «Send SOS» (в зависимости от версии – в приложении или долгим нажатием на значок приложения). pinn. сразу оповестит всех членов семьи push-уведомлением – с местоположением, адресом, временем и кнопками для звонка и вызова экстренных служб {regionNotrufText}. Совет: укажите свой мобильный номер в экстренной карте.",
  "loc.traccarClientChooseSend#wg": "В «Traccar Client» выберите «Send SOS» (в зависимости от версии – в приложении или долгим нажатием на значок приложения). pinn. сразу оповестит всех соседей push-уведомлением – с местоположением, адресом, временем и кнопками для звонка и вызова экстренных служб {regionNotrufText}. Совет: укажите свой мобильный номер в экстренной карте.",
