  "maint.auto.at": "в",
  "maint.auto.daily": "Каждый день",
  "maint.auto.enable": "Устанавливать новые версии автоматически",
  "maint.auto.hint": "В выбранное время pinn. проверяет наличие новой версии, сначала создаёт резервную копию, а затем устанавливает обновление. В это время pinn. несколько минут недоступен. Предварительные версии автоматически не устанавливаются.",
  "maint.auto.lastBusy": "Запланировано с {when} – сейчас идёт резервное копирование или обновление. pinn. пробует снова каждые 5 минут.",
