  "maint.dev.checking": "Поиск предварительных версий …",
  "maint.dev.confirm": "Я прочитал(а) указания и хочу протестировать предварительную версию на этом сервере.",
  "maint.dev.install": "Установить предварительную версию {version}",
  "maint.dev.installButton": "Установить предварительную версию",
  "maint.dev.installConfirm": "Установить предварительную версию {version} сейчас? Она может содержать ошибки и действует для всех семей на этом сервере. Перед этим автоматически создаётся резервная копия – через «Восстановить» можно в любой момент вернуться. pinn. будет недоступен несколько минут.",
  "maint.dev.intro": "Предварительные версии (на GitHub) – это тестовые версии перед готовой версией. Обычные обновления их никогда не показывают – здесь их можно найти намеренно.",
  "maint.dev.none": "Сейчас предварительной версии нет.",
  "maint.dev.notNewer": "Последняя предварительная версия {version} не новее вашей версии – у вас актуальная версия.",
  "maint.dev.released": "Последняя предварительная версия {version} уже вышла как готовая версия – используйте для неё обычное обновление.",
  "maint.dev.report": "Если вы что-то заметили, пожалуйста, сообщите об этом на GitHub – с версией, устройством и тем, что вы делали. В этом помогут сведения из журнала ошибок.",
  "maint.dev.safe": "Ваши данные не потеряются: перед установкой pinn. автоматически создаёт резервную копию («Перед обновлением»). Через «Восстановить» → «Всё» можно в любой момент вернуться к прежнему состоянию. Как только выйдет готовая версия, она будет предложена как обычное обновление.",
  "maint.dev.title": "🧪 Для разработчиков: тестировать предварительные версии",
  "maint.dev.warnBugs": "Предварительные версии могут содержать ошибки. Функции могут ещё измениться, быть незавершёнными или снова исчезнуть.",
  "maint.dev.warnDaily": "Не рекомендуется, если вы полагаетесь на pinn. в повседневной жизни – например, для встреч, напоминаний или экстренных карт.",
  "maint.dev.warnOffline": "Во время установки pinn. несколько минут недоступен.",
  "maint.dev.warnServer": "Обновление действует для всего сервера: после этого все семьи и все устройства будут использовать предварительную версию.",
