  "maint.err.damaged": "База данных в этой резервной копии повреждена – ничего не изменено.",
  "maint.err.docker": "У контейнера «wartung» нет доступа к Docker.",
  "maint.err.download": "Не удалось загрузить обновление с GitHub – пожалуйста, проверьте подключение NAS к интернету. Ничего не изменено.",
