  "settings.calendar.fromFamily#wg": "от квартиры · pinn.",
  "settings.calendar.info": "Каждый профиль входит в свой аккаунт iCloud или Google и отмечает в нём календари: «Для меня» видит только ваш профиль, «Семья» видят и используют все в вашей семье. Остальные видят лишь, из какого аккаунта взят семейный календарь – в скрытом виде, например m**l@g***l.com. События можно как обычно создавать, изменять, переносить и ставить в очередь офлайн – они попадают прямо в iCloud или Google (а значит, и на телефон). Синхронизация каждые 15 минут или по кнопке «Обновить сейчас». Без аккаунта тоже можно – календарь только на вашем сервере pinn. Напоминания и ежедневная сводка по push: личные события – только вам.",
  "settings.calendar.info#wg": "Каждый профиль входит в свой аккаунт iCloud или Google и отмечает в нём календари: «Для меня» видит только ваш профиль, «Квартира» видят и используют все в вашей квартире. Остальные видят лишь, из какого аккаунта взят общий календарь – в скрытом виде, например m**l@g***l.com. События можно как обычно создавать, изменять, переносить и ставить в очередь офлайн – они попадают прямо в iCloud или Google (а значит, и на телефон). Синхронизация каждые 15 минут или по кнопке «Обновить сейчас». Без аккаунта тоже можно – календарь только на вашем сервере pinn. Напоминания и ежедневная сводка по push: личные события – только вам.",
