  "settings.home.info": "Ваш дом действует для всей семьи: погода, праздники и школьные каникулы вашей федеральной земли в календаре, восход и закат (например, для детской страницы) и геолокация (место «Дом» с push при прибытии и уходе, карта начинается там). pinn. больше не запрашивает местоположение при каждом запуске. Поиск адреса идёт через ваш собственный сервер.",
