  "settings.members.childLockHint": "👤 Взрослый: без ограничений. 🔒 Ребёнок: детский режим – профиль не может ничего добавлять, изменять или удалять (отмечать выполненное можно), в настройках только просматривает, видит только свои задачи (включая «Все») и не имеет доступа к финансам, документам и транспорту; на панели — с PIN, как все. ⭐ Только детская страница: ребёнок видит только свою детскую страницу и открывает её на панели одним касанием — без пароля и PIN. Администраторов ограничить нельзя.",
