  "settings.outlook.intro": "Каждое воскресенье с 18:00 появляется обзор недели со всем важным для семьи на следующую неделю, а в последний день месяца с 18:00 – прогноз финансов на следующий месяц. Оба один раз появляются уведомлением вверху и как push – здесь их можно открыть снова в любое время.",
  "settings.outlook.intro#wg": "Каждое воскресенье с 18:00 появляется обзор недели со всем важным для квартиры на следующую неделю, а в последний день месяца с 18:00 – прогноз финансов на следующий месяц. Оба один раз появляются уведомлением вверху и как push – здесь их можно открыть снова в любое время.",
  "settings.outlook.introYear": "28 декабря с 18:00 появляются итоги года: расходы, приготовленные блюда и поездки. Они видны до 10 января, а открыть их можно здесь в любое время.",
